    pub(crate) fn poll_recv_pending() -> Poll<Option<T>> {
        Pending
    }

    pub(crate) fn poll_many_ready(count: usize) -> Poll<usize> {
        Ready(count)
    }

    pub(crate) fn poll_many_pending() -> Poll<usize> {
        Pending
    }

    pub(crate) fn handle_recv_pop<S: super::chan::Semaphore>(
        rx: &super::chan::Rx<T, S>,
        popped: Option<Read<T>>,
        coop: &crate::runtime::coop::RestoreOnPending,
    ) -> Option<Poll<Option<T>>> {
        match popped {
            Some(Read::Value(value)) => {
                Self::add_single_permit(rx);
                coop.made_progress();
                Some(Self::poll_ready_value(value))
            }
            Some(Read::Closed) => {
                assert!(Self::semaphore_is_idle(rx));
                coop.made_progress();
                Some(Self::poll_ready_disconnect())
            }
            None => None,
        }
    }

    pub(crate) fn finish_recv_after_wait<S: super::chan::Semaphore>(
        rx: &super::chan::Rx<T, S>,
        rx_fields: &super::chan::RxFields<T>,
        coop: &crate::runtime::coop::RestoreOnPending,
    ) -> Poll<Option<T>> {
        if Self::chan_rx_closed_and_idle(rx, rx_fields) {
            coop.made_progress();
            Self::poll_ready_disconnect()
        } else {
            Self::poll_recv_pending()
        }
    }

    pub(crate) fn finish_recv_many_after_wait<S: super::chan::Semaphore>(
        rx: &super::chan::Rx<T, S>,
        rx_fields: &super::chan::RxFields<T>,
        buffer: &Vec<T>,
        coop: &crate::runtime::coop::RestoreOnPending,
    ) -> Poll<usize> {
        if Self::chan_rx_closed_and_idle(rx, rx_fields) {
            assert!(buffer.is_empty());
            coop.made_progress();
            Self::poll_many_ready(0)
        } else {
            Self::poll_many_pending()
        }
    }

    pub(crate) fn bounded_map_acquire_to_value<U>(
        result: Result<(), TrySendError<()>>,
        value: U,
    ) -> Result<U, TrySendError<U>> {
        match result {
            Ok(()) => Ok(value),
            Err(TrySendError::Closed(())) => Err(TrySendError::Closed(value)),
            Err(TrySendError::Full(())) => Err(TrySendError::Full(value)),
        }
    }

    pub(crate) fn unbounded_try_add_two(curr: usize) -> Option<usize> {
        if Self::unbounded_closed_bit_set(curr) {
            None
        } else if Self::unbounded_count_overflowed(curr) {
            std::process::abort();
        } else {
            Some(curr + 2)
        }
    }

    pub(crate) fn list_tx_tail_is_closed_ptr(tail: *mut Block<T>) -> bool {
        unsafe { (*tail).is_closed() }
    }

    pub(crate) fn rx_index_matches_block(&self, index: usize) -> bool {
        debug_assert!(Self::list_index_at_block_start(Self::list_slot_start(index)));
        self.is_at_index(Self::list_slot_start(index))
    }

    pub(crate) fn can_reclaim_before(required_index: usize, rx_index: usize) -> bool {
        required_index <= rx_index
    }

    pub(crate) fn park_thread(park: &mut crate::runtime::park::CachedParkThread) {
        park.park();
    }

    pub(crate) fn new_cached_park_thread() -> crate::runtime::park::CachedParkThread {
        crate::runtime::park::CachedParkThread::new()
    }

    pub(crate) fn register_park_waker<S: super::chan::Semaphore>(
        rx: &super::chan::Rx<T, S>,
        park: &crate::runtime::park::CachedParkThread,
    ) {
        let waker = park.waker().unwrap();
        rx.inner.rx_waker.register_by_ref(&waker);
    }

    pub(crate) fn wake_rx_waker<S>(chan: &super::chan::Chan<T, S>) {
        chan.rx_waker.wake();
    }

    pub(crate) fn try_pop_ok(value: T) -> super::list::TryPopResult<T> {
        super::list::TryPopResult::Ok(value)
    }

    pub(crate) fn try_pop_closed() -> super::list::TryPopResult<T> {
        super::list::TryPopResult::Closed
    }

    pub(crate) fn try_pop_empty() -> super::list::TryPopResult<T> {
        super::list::TryPopResult::Empty
    }

    pub(crate) fn try_pop_busy() -> super::list::TryPopResult<T> {
        super::list::TryPopResult::Busy
    }

    pub(crate) fn classify_read_pop(result: Option<Read<T>>, tail_position: usize, index: usize) -> super::list::TryPopResult<T> {
        match result {
            Some(Read::Value(value)) => Self::try_pop_ok(value),
            Some(Read::Closed) => Self::try_pop_closed(),
            None => Self::classify_missing_pop(tail_position, index),
        }
    }

    pub(crate) fn chan_tx_count_is_zero<S: super::chan::Semaphore>(rx: &super::chan::Rx<T, S>) -> bool {
        rx.inner.tx_count.load(Acquire) == 0
    }

    pub(crate) fn list_free_head_caught_up(rx: &super::list::Rx<T>) -> bool {
        rx.free_head == rx.head
    }

    pub(crate) fn block_ptr_from_non_null(ptr: NonNull<Block<T>>) -> *mut Block<T> {
        ptr.as_ptr()
    }

    pub(crate) fn non_null_from_block_ptr(ptr: *mut Block<T>) -> NonNull<Block<T>> {
        unsafe { NonNull::new_unchecked(ptr) }
    }

    pub(crate) fn slot_distance_exceeds_offset(distance: usize, slot_offset: usize) -> bool {
        Self::should_try_updating_tail(distance, slot_offset)
    }

    pub(crate) fn yield_after_block_walk() {
        Self::yield_list_walk();
    }

    pub(crate) fn recv_many_limit_zero(limit: usize) -> bool {
        Self::recv_limit_is_zero(limit)
    }

    pub(crate) fn send_error_from_value<U>(value: U) -> SendError<U> {
        Self::send_closed(value)
    }

    pub(crate) fn try_recv_from_pop<S: super::chan::Semaphore>(
        rx: &super::chan::Rx<T, S>,
        result: super::list::TryPopResult<T>,
    ) -> Result<Option<T>, TryRecvError> {
        Self::map_try_pop_result(rx, result)
    }

    pub(crate) fn current_rx_has_value(rx: &super::list::Rx<T>) -> bool {
        Self::list_head_has_value(rx)
    }

    pub(crate) fn pending_list_len(rx: &super::list::Rx<T>, tx: &super::list::Tx<T>) -> usize {
        Self::list_pending_messages(rx, tx)
    }

    pub(crate) fn walk_unreclaimed_blocks(rx: &super::list::Rx<T>) -> NonNull<Block<T>> {
        Self::walk_free_head_to_head(rx)
    }

    pub(crate) fn observed_or_none(&self) -> Option<usize> {
        self.observed_tail_position()
    }

    pub(crate) fn fully_written(&self) -> bool {
        self.is_final()
    }

    pub(crate) fn released(&self) -> bool {
        self.block_is_released()
    }

    pub(crate) fn ready_or_closed(&self, slot_index: usize) -> bool {
        self.slot_ready_or_closed(slot_index)
    }
}

/// Returns `true` if the specified slot has a value ready to be consumed.
fn is_ready(bits: usize, slot: usize) -> bool {
    let mask = 1 << slot;
    mask == mask & bits
}

/// Returns `true` if the closed flag has been set.
fn is_tx_closed(bits: usize) -> bool {
    TX_CLOSED == bits & TX_CLOSED
}

impl<T> Values<T> {
    /// Initialize a `Values` struct from a pointer.
    ///
    /// # Safety
    ///
    /// The raw pointer must be valid for writing a `Values<T>`.
    unsafe fn initialize(_value: NonNull<Values<T>>) {
        // When fuzzing, `UnsafeCell` needs to be initialized.
        if_loom! {
            let p = _value.as_ptr() as *mut UnsafeCell<MaybeUninit<T>>;
            for i in 0..BLOCK_CAP {
                p.add(i)
                    .write(UnsafeCell::new(MaybeUninit::uninit()));
            }
        }
    }
}

impl<T> ops::Index<usize> for Values<T> {
    type Output = UnsafeCell<MaybeUninit<T>>;

    fn index(&self, index: usize) -> &Self::Output {
        self.0.index(index)
    }
}

